INSERT INTO `v1_4c8dda404bfe86384ab9699c4b15c8d7ad3e75b1e902ffe1c5914fec513d6c1c` VALUES ("スタンダードコレクションではポスターやペナントなど\n部屋に飾れる定番グッズが盛りだくさん！\nあなたの部屋をカルミナで彩ろう！", 1, "スタンダードコレクション", 1, 3, "1回メダル{0}枚！\n定番グッズであなたの部屋をカルミナで彩ろう！");
INSERT INTO `v1_4c8dda404bfe86384ab9699c4b15c8d7ad3e75b1e902ffe1c5914fec513d6c1c` VALUES ("プレミアムコレクションではサイン色紙や\nブロマイドなど、★★以上のグッズが盛りだくさん！\nレアグッズをたくさんゲットしよう！", 1, "プレミアムコレクション", 2, 10, "1回メダル{0}枚！\nメンバー直筆サイン色紙など、★★以上のグッズを確定でゲット！");
INSERT INTO `v1_4c8dda404bfe86384ab9699c4b15c8d7ad3e75b1e902ffe1c5914fec513d6c1c` VALUES ("フェスコレクションではカルミナサマーライブで\n大活躍するグッズが勢ぞろい！\nゲットしたグッズを片手に、いざライブ会場へ！", 1, "フェスコレクション", 3, 3, "1回メダル{0}枚！\nカルミナライブに参加する際のマストアイテムをゲットしよう！");
